output_file = "folder_structure_report.txt"

def get_folder_structure(root_path, indent=0):
    structure = ""
    for item in sorted(os.listdir(root_path)):
        item_path = os.path.join(root_path, item)
        if os.path.isdir(item_path):
            structure += "    " * indent + f"📁 {item}\n"
            structure += get_folder_structure(item_path, indent + 1)
        else:
            structure += "    " * indent + f"📄 {item}\n"
    return structure

with open(output_file, "w", encoding="utf-8") as f:
    for folder in os.listdir(base_path):
        folder_path = os.path.join(base_path, folder)
        if not os.path.isdir(folder_path):
            continue
        
        # Проверяем, содержит ли название папки номер из списка nums
        folder_number = None
        for num in nums:
            if num in folder:
                folder_number = num
                break
        
        if folder_number:
            f.write(f"\n Закупка № {folder_number}\n")
        else:
            f.write(f"\n {folder}\n")
        
        # Получаем структуру подпапок и файлов
        f.write(get_folder_structure(folder_path))
get_folder_structure(base_path)